"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[191],{6343:(a,n,s)=>{s.r(n),s.d(n,{data:()=>e});const e={key:"v-d8bfacea",path:"/setup/",title:"Setup",lang:"en-US",frontmatter:{},excerpt:"",headers:[{level:2,title:"Requirements",slug:"requirements",children:[{level:3,title:"Install ImageMagick",slug:"install-imagemagick",children:[]}]},{level:2,title:"Install dammy",slug:"install-dammy",children:[]},{level:2,title:"Uninstall",slug:"uninstall",children:[]}],filePathRelative:"setup/README.md",git:{updatedTime:1779339153e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:2}]}}},6627:(a,n,s)=>{s.r(n),s.d(n,{default:()=>i});const e=(0,s(6252).uE)('<h1 id="setup" tabindex="-1"><a class="header-anchor" href="#setup" aria-hidden="true">#</a> Setup</h1><h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements" aria-hidden="true">#</a> Requirements</h2><ul><li><strong>Bash</strong> — dammy is a Bash script. It runs on macOS and Linux.</li><li><strong>ImageMagick</strong> — Required only when generating image files (jpg, png, gif, etc.). If ImageMagick is not installed and you specify an image format, dammy will show an error with installation instructions and exit.</li></ul><h3 id="install-imagemagick" tabindex="-1"><a class="header-anchor" href="#install-imagemagick" aria-hidden="true">#</a> Install ImageMagick</h3><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code><span class="token comment"># macOS</span>\n$ brew <span class="token function">install</span> imagemagick\n\n<span class="token comment"># Ubuntu / Debian</span>\n$ <span class="token function">sudo</span> <span class="token function">apt</span> <span class="token function">install</span> imagemagick\n\n<span class="token comment"># CentOS / RHEL</span>\n$ <span class="token function">sudo</span> yum <span class="token function">install</span> imagemagick\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="install-dammy" tabindex="-1"><a class="header-anchor" href="#install-dammy" aria-hidden="true">#</a> Install dammy</h2><p>Clone the repository and add the directory to your <code>PATH</code>.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ <span class="token function">git</span> clone https://github.com/ontheroadjp/dammy\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br></div></div><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code><span class="token comment"># for bash</span>\n$ <span class="token builtin class-name">echo</span> <span class="token string">&#39;export PATH=/path/to/dammy:$PATH&#39;</span> <span class="token operator">&gt;&gt;</span> ~/.bash_profile\n\n<span class="token comment"># for zsh</span>\n$ <span class="token builtin class-name">echo</span> <span class="token string">&#39;export PATH=/path/to/dammy:$PATH&#39;</span> <span class="token operator">&gt;&gt;</span> ~/.zprofile\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Reload your shell and verify:</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh --version\ndammy v1.3.5\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="custom-container tip"><p class="custom-container-title">TIP</p><p>dammy only creates files under your <code>HOME</code> directory. Absolute paths and paths containing <code>../</code> are rejected for safety.</p></div><h2 id="uninstall" tabindex="-1"><a class="header-anchor" href="#uninstall" aria-hidden="true">#</a> Uninstall</h2><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ <span class="token function">rm</span> -rf /path/to/dammy\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br></div></div><p>Then remove the <code>PATH</code> line you added to <code>.bash_profile</code> or <code>.zprofile</code>.</p>',15),l={},i=(0,s(3744).Z)(l,[["render",function(a,n){return e}]])},3744:(a,n)=>{n.Z=(a,n)=>{const s=a.__vccOpts||a;for(const[a,e]of n)s[a]=e;return s}}}]);